using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class PayrollAdjustmentTests
{
 class User(int id=1,int? emp=null,bool grant=true):ICurrentUser{public string Email=>$"actor{id}@example.local";public int? EmployeeId=>emp;public int UserId=>id;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>p!=Perm.PayAdjust||grant;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PayrollService Pay(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var n=new NotificationService(d,u,c);return new(d,u,a,n,new AttendanceService(d,new AccessScope(d,u),u,a,n,c,new WorkflowService(d,u,a)),c);}
 static PayrollAdjustments S(AppDbContext d,int actor=1,int? emp=null,bool grant=true){var u=new User(actor,emp,grant);var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c),Pay(d,u));}
 static async Task<(int,int,int)> Runs(AppDbContext d){var target=await Pay(d,new User()).CreateAsync(2027,9);var source=await d.Set<PayrollLine>().FirstAsync(x=>x.RunId==1);var line=await d.Set<PayrollLine>().SingleAsync(x=>x.RunId==target&&x.EmployeeId==source.EmployeeId);return(source.Id,target,line.Id);}
 [Fact]public async Task SeparateInitiallyUnsetGrantAndValidatedReferences(){await using var d=await Db();var(source,target,line)=await Runs(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,grant:false).ListAsync(target));Assert.DoesNotContain(await d.Set<RolePermission>().ToListAsync(),x=>x.Permission==Perm.PayAdjust);foreach(var amount in new[]{0m,-1m,1.001m,100000001m})await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(source,target,"Earning",amount,"test"));await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(source,target,"other",100,"test"));await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(source,target,"Earning",100,""));await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(line,target,"Earning",100,"draft source"));Assert.Empty(await d.Set<PayrollAdjustment>().ToListAsync());}
 [Fact]public async Task IndependentDecisionThenExactlyOnceExplicitApplyPreservesSource(){await using var d=await Db();var(source,target,lineId)=await Runs(d);var original=(await d.Set<PayrollLine>().FindAsync(source))!.Net;var line=(await d.Set<PayrollLine>().FindAsync(lineId))!;var bonus=line.Bonus;await S(d).ProposeAsync(source,target,"Earning",123.45m,"Fictional prior period correction");var p=await d.Set<PayrollAdjustment>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyAsync(p.Id,"unapproved"));await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).ReviewAsync(target));await Assert.ThrowsAsync<DomainException>(()=>S(d).DecideAsync(p.Id,true,"self"));await Assert.ThrowsAsync<DomainException>(()=>S(d,2,p.EmployeeId).DecideAsync(p.Id,true,"subject"));await S(d,2).DecideAsync(p.Id,true,"Checked source evidence");await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).ReviewAsync(target));await S(d).ApplyAsync(p.Id,"Apply approved correction");Assert.Equal(bonus+123.45m,(await d.Set<PayrollLine>().FindAsync(lineId))!.Bonus);Assert.Equal(original,(await d.Set<PayrollLine>().FindAsync(source))!.Net);await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyAsync(p.Id,"duplicate"));Assert.Equal(new[]{"Approved","Applied"},(await d.Set<PayrollAdjustmentEvent>().OrderBy(x=>x.Id).ToListAsync()).Select(x=>x.Action));await Pay(d,new User()).RecalculateAsync(target);Assert.Equal(bonus+123.45m,(await d.Set<PayrollLine>().SingleAsync(x=>x.RunId==target&&x.EmployeeId==p.EmployeeId)).Bonus);}
 [Fact]public async Task RejectedCannotApplyAndLockedTargetCannotDecide(){await using var d=await Db();var(source,target,line)=await Runs(d);await S(d).ProposeAsync(source,target,"Deduction",50,"Correction");var p=await d.Set<PayrollAdjustment>().SingleAsync();await S(d,2).DecideAsync(p.Id,false,"Evidence insufficient");await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyAsync(p.Id,"no"));await Assert.ThrowsAsync<DomainException>(()=>S(d,3).DecideAsync(p.Id,true,"replace decision"));(await d.Set<PayrollRun>().FindAsync(target))!.Status=PayrollStatus.Finalized;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).ProposeAsync(source,target,"Earning",20,"no"));}
 [Fact]public async Task SourceAndDecisionEvidenceCannotBeEditedOrDeleted(){await using var d=await Db();var(source,target,line)=await Runs(d);await S(d).ProposeAsync(source,target,"Earning",10,"Original");var p=await d.Set<PayrollAdjustment>().SingleAsync();await S(d,2).DecideAsync(p.Id,true,"Original decision");p.Amount=900;await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();d.Remove(await d.Set<PayrollAdjustmentEvent>().SingleAsync());await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task SequenceConstraintPreventsCompetingApprovalAndRejection(){await using var d=await Db();d.Add(new PayrollAdjustmentEvent{AdjustmentId=999,Sequence=1,Action="Approved"});await d.SaveAsync();d.Add(new PayrollAdjustmentEvent{AdjustmentId=999,Sequence=1,Action="Rejected"});await Assert.ThrowsAsync<DbUpdateException>(()=>d.SaveAsync());}
 [Fact]public async Task DeductionAddsToManualTotalButCannotCreateNegativeNet(){await using var d=await Db();var(source,target,lineId)=await Runs(d);var line=(await d.Set<PayrollLine>().FindAsync(lineId))!;var old=line.OtherDeduction;await S(d).ProposeAsync(source,target,"Deduction",10,"Fictional deduction");var p=await d.Set<PayrollAdjustment>().SingleAsync();await S(d,2).DecideAsync(p.Id,true,"Checked");await S(d).ApplyAsync(p.Id,"Apply");Assert.Equal(old+10,(await d.Set<PayrollLine>().FindAsync(lineId))!.OtherDeduction);await S(d).ProposeAsync(source,target,"Deduction",100000000,"Excess");p=await d.Set<PayrollAdjustment>().OrderByDescending(x=>x.Id).FirstAsync();await S(d,2).DecideAsync(p.Id,true,"Checked amount only");await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyAsync(p.Id,"Refused below zero"));Assert.Equal(old+10,(await d.Set<PayrollLine>().FindAsync(lineId))!.OtherDeduction);}

 [Fact]public async Task ProposerCanWithdrawUnappliedButNeverAppliedEvidence(){await using var d=await Db();var(source,target,line)=await Runs(d);await S(d).ProposeAsync(source,target,"Deduction",100,"Proposal");var p=await d.Set<PayrollAdjustment>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,2).CancelAsync(p.Id,"Not proposer"));await S(d,2).DecideAsync(p.Id,true,"Approved");await S(d).CancelAsync(p.Id,"Withdraw before application");await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyAsync(p.Id,"Already cancelled"));await Pay(d,new User()).ReviewAsync(target);Assert.Equal(PayrollStatus.HRReviewed,(await d.Set<PayrollRun>().FindAsync(target))!.Status);}

 [Fact]public async Task ManualEditCannotEraseAppliedCorrectionAmounts(){await using var d=await Db();var(source,target,lineId)=await Runs(d);await S(d).ProposeAsync(source,target,"Earning",123.45m,"Approved earning");var earning=await d.Set<PayrollAdjustment>().SingleAsync();await S(d,2).DecideAsync(earning.Id,true,"Checked");await S(d).ApplyAsync(earning.Id,"Apply");await S(d).ProposeAsync(source,target,"Deduction",10m,"Approved deduction");var deduction=await d.Set<PayrollAdjustment>().OrderByDescending(x=>x.Id).FirstAsync();await S(d,2).DecideAsync(deduction.Id,true,"Checked");await S(d).ApplyAsync(deduction.Id,"Apply");var before=(await d.Set<PayrollLine>().FindAsync(lineId))!.Net;await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).AdjustLineAsync(lineId,0,10,"Cannot erase earning"));await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).AdjustLineAsync(lineId,123.45m,0,"Cannot erase deduction"));Assert.Equal(before,(await d.Set<PayrollLine>().FindAsync(lineId))!.Net);await Pay(d,new User()).AdjustLineAsync(lineId,133.45m,20,"Additional manual totals");await Pay(d,new User()).RecalculateAsync(target);var line=await d.Set<PayrollLine>().SingleAsync(x=>x.RunId==target&&x.EmployeeId==earning.EmployeeId);Assert.Equal(133.45m,line.Bonus);Assert.Equal(20,line.OtherDeduction-line.FixedDeduction);}
 [Theory][InlineData("1.001")][InlineData("100000001")]public async Task ManualTotalsMustBeBoundedCentAmounts(string amount){await using var d=await Db();var(source,target,line)=await Runs(d);var value=decimal.Parse(amount,System.Globalization.CultureInfo.InvariantCulture);await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).AdjustLineAsync(line,value,0,"Invalid amount"));await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).AdjustLineAsync(line,0,value,"Invalid amount"));}

 [Fact]public async Task RecalculationCannotDropAppliedEmployeeAndReviewRejectsMissingTotals(){await using var d=await Db();var(source,target,lineId)=await Runs(d);await S(d).ProposeAsync(source,target,"Earning",10,"Approved correction");var p=await d.Set<PayrollAdjustment>().SingleAsync();await S(d,2).DecideAsync(p.Id,true,"Checked");await S(d).ApplyAsync(p.Id,"Apply");(await d.Set<Employee>().FindAsync(p.EmployeeId))!.Status=EmployeeStatus.Terminated;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).RecalculateAsync(target));Assert.NotNull(await d.Set<PayrollLine>().FindAsync(lineId));var line=(await d.Set<PayrollLine>().FindAsync(lineId))!;Assert.Equal(10,line.Bonus);line.Bonus=0;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>Pay(d,new User()).ReviewAsync(target));Assert.Equal(PayrollStatus.Draft,(await d.Set<PayrollRun>().FindAsync(target))!.Status);}

}
